export interface GeneratedDocHeader {
  /** Repo-relative path of the generator module. */
  generator: string;
  /** Repo-relative path or glob the doc is generated from. */
  source: string;
  title: string;
}

/** The lines every Generated Doc starts with: front matter, title and the do-not-edit note. */
export function generatedDocHeader({ generator, source, title }: GeneratedDocHeader): string[] {
  return [
    '---',
    'kind: generated',
    `generator: ${generator}`,
    `source: ${source}`,
    '---',
    '',
    `# ${title}`,
    '',
    '> Generated by `pnpm docs:generate`. Do not edit by hand.',
    '',
  ];
}
